func (q *RunsQuery) Compute(col keel.Column, e keel.Expr) keel.Query[*analysis.Run] {
	q.QueryCore.Compute(col, e)
	return q
}

// LoadStrategy chooses how the query's relations load.
func (q *RunsQuery) LoadStrategy(s keel.LoadStrategy) keel.Query[*analysis.Run] {
	q.QueryCore.LoadStrategy(s)
	return q
}

// Clone returns an independent copy of the query.
func (q *RunsQuery) Clone() keel.Query[*analysis.Run] {
	return &RunsQuery{QueryCore: *q.QueryCore.Clone()}
}

// One returns the only matching row, or keel.ErrNotFound or keel.ErrNotSingular.
func (q *RunsQuery) One(ctx context.Context, db *keel.DB) (*analysis.Run, error) {
	return keel.One[*analysis.Run](ctx, db, &q.QueryCore)
}

// First returns the first row in the query's order, or keel.ErrNotFound.
func (q *RunsQuery) First(ctx context.Context, db *keel.DB) (*analysis.Run, error) {
	return keel.First[*analysis.Run](ctx, db, &q.QueryCore)
}

// List returns the matching rows. The query must have a Limit.
func (q *RunsQuery) List(ctx context.Context, db *keel.DB) ([]*analysis.Run, error) {
	return keel.List[*analysis.Run](ctx, db, &q.QueryCore)
}

// All returns every matching row. Use it only for sets known to be small.
func (q *RunsQuery) All(ctx context.Context, db *keel.DB) ([]*analysis.Run, error) {
	return keel.All[*analysis.Run](ctx, db, &q.QueryCore)
}

// UpdateReturning sets columns on every matching row and returns the updated rows.
func (q *RunsQuery) UpdateReturning(ctx context.Context, db *keel.DB, sets ...keel.Assignment) ([]*analysis.Run, error) {
	return keel.UpdateReturning[*analysis.Run](ctx, db, &q.QueryCore, sets...)
}

// Page returns the page of rows after the request's cursor.
func (q *RunsQuery) Page(ctx context.Context, db *keel.DB, p keel.PageRequest) (keel.Page[*analysis.Run], error) {
	return keel.PageOf[*analysis.Run](ctx, db, &q.QueryCore, p)
}

// Each runs the query page by page and calls fn with each batch of at most size rows.
func (q *RunsQuery) Each(ctx context.Context, db *keel.DB, size int, fn func(ctx context.Context, batch []*analysis.Run) error) error {
	return keel.Each[*analysis.Run](ctx, db, &q.QueryCore, size, fn)
}

func newRun() unsafe.Pointer { return unsafe.Pointer(new(analysis.Run)) }

func newNRun(n int) unsafe.Pointer { return unsafe.Pointer(unsafe.SliceData(make([]analysis.Run, n))) }

func ptrRun(p unsafe.Pointer, c int32) any {
	r := (*analysis.Run)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.Status))
	case 4:
		return &r.Title
	case 5:
		return &r.Purpose
	case 6:
		return &r.Code
	case 7:
		return &r.Datasets
	case 8:
		return &r.Output
	case 9:
		return &r.Tables
	case 10:
		return &r.Figures
	case 11:
		return &r.Charts
	case 12:
		return &r.Layout
	case 13:
		return &r.ErrorName
	case 14:
		return &r.ErrorValue
	case 15:
		return &r.Traceback
	case 16:
		return &r.Failure
	case 17:
		return &r.DurationMs
	case 18:
		return (*string)(unsafe.Pointer(&r.AgentDefinitionID))
	case 19:
		return (*string)(unsafe.Pointer(&r.AgentRunID))
	case 20:
		return (*string)(unsafe.Pointer(&r.ThreadID))
	case 21:
		return (*string)(unsafe.Pointer(&r.RequestedByID))
	case 22:
		return &r.StartedAt
	case 23:
		return &r.FinishedAt
	case 24:
		return &r.CreatedAt
	}
	return nil
}

func valueRun(p unsafe.Pointer, c int32) any {
	r := (*analysis.Run)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.Status)
	case 4:
		return r.Title
	case 5:
		return r.Purpose
	case 6:
		return r.Code
	case 7:
		if r.Datasets == nil {
			return keel.EmptyJSONArray
		}
		return r.Datasets
	case 8:
		return r.Output
	case 9:
		if r.Tables == nil {
			return keel.EmptyJSONArray
		}
		return r.Tables
	case 10:
		if r.Figures == nil {
			return keel.EmptyJSONArray
		}
		return r.Figures
	case 11:
		if r.Charts == nil {
			return keel.EmptyJSONArray
		}
		return r.Charts
	case 12:
		if r.Layout == nil {
			return keel.EmptyJSONArray
		}
		return r.Layout
	case 13:
		return r.ErrorName
	case 14:
		return r.ErrorValue
	case 15:
		return r.Traceback
	case 16:
		return r.Failure
	case 17:
		return r.DurationMs
	case 18:
		if r.AgentDefinitionID == "" {
			return nil
		}
		return string(r.AgentDefinitionID)
	case 19:
		if r.AgentRunID == "" {
			return nil
		}
		return string(r.AgentRunID)
	case 20:
		if r.ThreadID == "" {
			return nil
		}
		return string(r.ThreadID)
	case 21:
		if r.RequestedByID == "" {
			return nil
		}
		return string(r.RequestedByID)
	case 22:
		return r.StartedAt
	case 23:
		return r.FinishedAt
	case 24:
		return r.CreatedAt
	}
	return nil
}

var enumStatus = [...]schema.EnumValue{
	{Value: `Succeeded`, Label: `Succeeded`},
	{Value: `Errored`, Label: `Errored`},
	{Value: `Stopped`, Label: `Stopped`},
	{Value: `TimedOut`, Label: `Timed Out`},
	{Value: `Failed`, Label: `Failed`},
}

// StatusCol is a column of analysis.Status values.
type StatusCol struct{ keel.StringCol }

func (c StatusCol) Eq(v analysis.Status) keel.Pred  { return c.StringCol.Eq(string(v)) }
func (c StatusCol) Ne(v analysis.Status) keel.Pred  { return c.StringCol.Ne(string(v)) }
func (c StatusCol) Gt(v analysis.Status) keel.Pred  { return c.StringCol.Gt(string(v)) }
func (c StatusCol) Gte(v analysis.Status) keel.Pred { return c.StringCol.Gte(string(v)) }
func (c StatusCol) Lt(v analysis.Status) keel.Pred  { return c.StringCol.Lt(string(v)) }
func (c StatusCol) Lte(v analysis.Status) keel.Pred { return c.StringCol.Lte(string(v)) }
func (c StatusCol) IsDistinctFrom(v analysis.Status) keel.Pred {
	return c.StringCol.IsDistinctFrom(string(v))
}
func (c StatusCol) Between(lo, hi analysis.Status) keel.Pred {
	return c.StringCol.Between(string(lo), string(hi))
}
func (c StatusCol) To(v analysis.Status) keel.Assignment { return c.StringCol.To(string(v)) }
func (c StatusCol) In(vs ...analysis.Status) keel.Pred   { return c.StringCol.In(keel.Strings(vs)...) }
func (c StatusCol) NotIn(vs ...analysis.Status) keel.Pred {
	return c.StringCol.NotIn(keel.Strings(vs)...)
}
